export type createCategoryResponse201 = {
  data: CategoryResponseDto
  status: 201
}

export type createCategoryResponse400 = {
  data: ApiErrorResponseDto
  status: 400
}

export type createCategoryResponse409 = {
  data: ApiErrorResponseDto
  status: 409
}

export type createCategoryResponseSuccess = (createCategoryResponse201) & {
  headers: Headers;
};
export type createCategoryResponseError = (createCategoryResponse400 | createCategoryResponse409) & {
  headers: Headers;
};

export type createCategoryResponse = (createCategoryResponseSuccess | createCategoryResponseError)

export const getCreateCategoryUrl = () => {




  return `/api/categories`
}

/**
 * Category names are unique case-insensitively: "Health", "health" and "  HEALTH  " are considered the same category.
 * @summary Create a category
 */
export const createCategory = async (createCategoryDto: CreateCategoryDto, options?: Parameters<typeof fetcher>[1]): Promise<createCategoryResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return fetcher<createCategoryResponse>(getCreateCategoryUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(createCategoryDto)
  }
);}





export const getCreateCategoryMutationKey = () => ['createCategory'] as const;

export const getCreateCategoryMutationOptions = <TError = ApiErrorResponseDto,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createCategory>>, TError,CreateCategoryMutationVariables, TContext>, request?: SecondParameter<typeof fetcher>}
): UseMutationOptions<Awaited<ReturnType<typeof createCategory>>, TError,CreateCategoryMutationVariables, TContext> => {

const mutationKey = getCreateCategoryMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createCategory>>, CreateCategoryMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  createCategory(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateCategoryMutationResult = NonNullable<Awaited<ReturnType<typeof createCategory>>>
    export type CreateCategoryMutationBody = CreateCategoryDto
    export type CreateCategoryMutationError = ApiErrorResponseDto
    export type CreateCategoryMutationVariables = {data: CreateCategoryDto}

    /**
 * @summary Create a category
 */
export const useCreateCategory = <TError = ApiErrorResponseDto,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createCategory>>, TError,CreateCategoryMutationVariables, TContext>, request?: SecondParameter<typeof fetcher>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof createCategory>>,
        TError,
        CreateCategoryMutationVariables,
        TContext
      > => {
      return useMutation(getCreateCategoryMutationOptions(options), queryClient);
    }
